      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.4/semantic-md-v1.0.4-darwin-arm64.tar.gz"
      sha256 "b110d034b7e06ca95659ad92238e4093e22b1e8a805726f35e2483ec6ade824d"
    end
    if Hardware::CPU.intel?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.4/semantic-md-v1.0.4-darwin-amd64.tar.gz"
      sha256 "7be1e5b8e3f8710ddeceed660b544d296e1170414d3deba5dfa5388cb2b2d076"
    end
  end

  on_linux do
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.4/semantic-md-v1.0.4-linux-arm64.tar.gz"
      sha256 "64fbc2a1bb3028d2a2aeaff9363302f334c64cfe6b2974c75260b53441accb9e"
    end
    if Hardware::CPU.intel?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.4/semantic-md-v1.0.4-linux-amd64.tar.gz"
      sha256 "73c04b199d31eeb9ada08a655e3836db158ec25f508fab6c6029343af87dfb7d"
    end
  end

  def install
    bin.install "semantic-md-darwin-arm64" => "semantic-md" if OS.mac? && Hardware::CPU.arm?
