    bin.install "semantic-md-linux-arm64" => "semantic-md" if OS.linux? && Hardware::CPU.arm?
    bin.install "semantic-md-linux-amd64" => "semantic-md" if OS.linux? && Hardware::CPU.intel?
  end

  test do
    assert_match "semantic-md version", shell_output("#{bin}/semantic-md version")
